await page.reload();await page.waitForTimeout(200);report.restore=await page.evaluate(()=>({floor:document.querySelector('#floorNum').textContent,str:document.querySelector('#strStat').textContent,points:document.querySelector('#pointsText').textContent,relics:document.querySelectorAll('.relic-row').length,npcStatus:document.querySelector('#npcStatus').textContent}));
await page.setViewportSize({width:390,height:844});await page.waitForTimeout(150);report.mobile=await page.evaluate(()=>({bodyWidth:document.body.scrollWidth,viewport:document.documentElement.clientWidth,overflow:document.body.scrollWidth>document.documentElement.clientWidth,npcPanel:document.querySelector('#npcPanel').getBoundingClientRect().toJSON(),chatForm:document.querySelector('#chatForm').getBoundingClientRect().toJSON()}));
await page.evaluate(()=>{let s=JSON.parse(localStorage.getItem('ascendant-save'));s.floor=1;s.points=0;localStorage.setItem('ascendant-save',JSON.stringify(s));location.reload()});await page.waitForTimeout(200);report.relocked=await page.evaluate(()=>({floor:document.querySelector('#floorNum').textContent,chatDisabled:document.querySelector('#chatInput').disabled,npcButtons:[...document.querySelectorAll('.npc-choices button')].every(b=>b.disabled)}));report.errors=errors;console.log(JSON.stringify(report,null,2));if(errors.length||report.mobile.overflow||report.floor1Locked.chatDisabled!==true||report.relocked.chatDisabled!==true||report.safeUI.status!=='OPEN'||report.statAllocation.str!=='16'||report.restore.str!=='16')process.exitCode=1;
} catch(e){console.error(e);process.exitCode=1}finally{if(browser)await browser.close();server.close()}})();
